#include "lstm_bidirectional_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/tiling_api.h"

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入 x 的形状: [B, S, I]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const auto& x_dims = x_shape->GetOriginShape().GetDims();
    if (x_dims.size() != 3) {
        return ge::GRAPH_FAILED;
    }
    uint32_t B = static_cast<uint32_t>(x_dims[0]);
    uint32_t S = static_cast<uint32_t>(x_dims[1]);
    uint32_t I = static_cast<uint32_t>(x_dims[2]);

    // h0 的形状: [2 * num_layers, B, H]，取 H 以得到 2H 输出维度
    const gert::Shape* h0_shape = context->GetInputShape(1);
    const auto& h0_dims = h0_shape->GetOriginShape().GetDims();
    if (h0_dims.size() != 3) {
        return ge::GRAPH_FAILED;
    }
    uint32_t H = static_cast<uint32_t>(h0_dims[2]);

    // Sum 临时缓冲区大小(按文档获取最小值即可保证正确性)
    uint32_t dtypesize = 4; // float32
    uint32_t maxValue = 0;
    uint32_t minValue = 0;
    AscendC::GetSumMaxMinTmpSize(I, dtypesize, false, maxValue, minValue);

    uint32_t outter = B * S;
    // inner 需要 32B 对齐: inner = ceil((n * sizeof(T))/32) * (32/sizeof(T))
    uint32_t inner = ((I * dtypesize + 32 - 1) / 32) * (32 / dtypesize);
    uint32_t outFeature = 2 * H;

    LstmBidirectionalCustomTilingData tiling;
    tiling.set_tmpSize(minValue);
    tiling.set_outter(outter);
    tiling.set_inner(inner);
    tiling.set_n(I);
    tiling.set_outFeature(outFeature);

    // 设置 BlockDim
    context->SetBlockDim(8);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 无需 workspace
    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // 输出 y 形状: [B, S, 2H]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const auto& x_dims = x_shape->GetOriginShape().GetDims();
    if (x_dims.size() != 3) {
        return GRAPH_FAILED;
    }
    const gert::Shape* h0_shape = context->GetInputShape(1);
    const auto& h0_dims = h0_shape->GetOriginShape().GetDims();
    if (h0_dims.size() != 3) {
        return GRAPH_FAILED;
    }
    int64_t B = x_dims[0];
    int64_t S = x_dims[1];
    int64_t H = h0_dims[2];
    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(3);
    y_shape->SetDim(0, B);
    y_shape->SetDim(1, S);
    y_shape->SetDim(2, 2 * H);
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext* context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return GRAPH_SUCCESS;
}
}

